const API_URL = 'http://localhost:8000/books';

export async function listBooks() {
  const response = await fetch(API_URL);
  if (!response.ok) {
    throw new Error('Failed to fetch books');
  }
  return response.json();
}

export async function createBook(book) {
  const response = await fetch(API_URL, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(book),
  });
  if (!response.ok) {
    throw new Error('Failed to create book');
  }
  return response.json();
}

export async function updateBookStatus(id, status) {
  const response = await fetch(`${API_URL}/${id}`, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ status }),
  });
  if (!response.ok) {
    throw new Error('Failed to update book status');
  }
  return response.json();
}

import { useState, useEffect } from 'react';
import { listBooks, updateBookStatus } from '../api';

export default function BookList({ refreshTrigger, onStatusUpdate }) {
  const [books, setBooks] = useState([]);
  const [error, setError] = useState(null);

  const fetchBooks = async () => {
    try {
      const data = await listBooks();
      setBooks(data);
    } catch (err) {
      setError(err.message);
    }
  };

  useEffect(() => {
    fetchBooks();
  }, [refreshTrigger]);

  const handleStatusChange = async (id, newStatus) => {
    try {
      await updateBookStatus(id, newStatus);
      fetchBooks();
      if (onStatusUpdate) {
        onStatusUpdate();
      }
    } catch (err) {
      alert('Failed to update status: ' + err.message);
    }
  };

  if (error) {
    return <div className="error">Error: {error}</div>;
  }

  return (
    <div className="book-list-container">
      <h2>I Miei Libri</h2>
      {books.length === 0 ? (
        <p>Nessun libro trovato.</p>
      ) : (
        <ul className="book-list">
          {books.map((book) => (
            <li key={book.id} className="book-item">
              <div>
                <strong>{book.title}</strong> di {book.author}
              </div>
              <div className="book-status-control">
                <span>Stato: </span>
                <select
                  value={book.status || 'to-read'}
                  onChange={(e) => handleStatusChange(book.id, e.target.value)}
                >
                  <option value="to-read">Da leggere</option>
                  <option value="reading">In lettura</option>
                  <option value="done">Letto</option>
                </select>
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

import { useState } from 'react';
import { createBook } from '../api';

export default function BookForm({ onBookCreated }) {
  const [title, setTitle] = useState('');
  const [author, setAuthor] = useState('');
  const [status, setStatus] = useState('to-read');
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError(null);

    if (!title || !author) {
      setError('Title and Author are required');
      return;
    }

    try {
      await createBook({ title, author, status });
      setTitle('');
      setAuthor('');
      setStatus('to-read');
      if (onBookCreated) {
        onBookCreated();
      }
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <div className="book-form-container">
      <h2>Aggiungi un Libro</h2>
      {error && <div className="error-message" style={{ color: 'red' }}>{error}</div>}
      <form onSubmit={handleSubmit} className="book-form">
        <div className="form-group">
          <label htmlFor="title">Titolo:</label>
          <input
            type="text"
            id="title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="E.g., Il signore degli anelli"
          />
        </div>
        <div className="form-group">
          <label htmlFor="author">Autore:</label>
          <input
            type="text"
            id="author"
            value={author}
            onChange={(e) => setAuthor(e.target.value)}
            placeholder="E.g., J.R.R. Tolkien"
          />
        </div>
        <div className="form-group">
          <label htmlFor="status">Stato:</label>
          <select
            id="status"
            value={status}
            onChange={(e) => setStatus(e.target.value)}
          >
            <option value="to-read">Da leggere</option>
            <option value="reading">In lettura</option>
            <option value="done">Letto</option>
          </select>
        </div>
        <button type="submit">Aggiungi</button>
      </form>
    </div>
  );
}

